mapper.select:
select author_user_id, show_on_profile, profile_pinned_at, profile_sort_order
from content_items
where id = #{contentId}

select count(*)
from follows
where follower_id = #{followerId} and following_id = #{followingId}

select following_count
from user_social_stats
where user_id = #{userId}

select follower_count
from user_social_stats
where user_id = #{userId}

mapper.update:
update content_items
set show_on_profile = #{showOnProfile},
    profile_pinned_at = #{pinnedAt},
    profile_sort_order = #{sortOrder}
where id = #{contentId}
